starter.stylesheet:
:root {
  --primary-main: #{{ .primary_main }};
  --secondary-main: #{{ .secondary_main }};
  --text-primary: #{{ .text_primary }};
  --text-secondary: #{{ .text_secondary }};
  --text-muted: #{{ .text_muted }};
  --link-color: #{{ .link_color }};
  --error-color: #{{ .error_color }};
  --background: #{{ .background }};
  --card-background: #{{ .card_background }};
  --card-border: #{{ .card_border }};
  --input-background: #{{ .input_background }};
  --input-border: #{{ .input_border }};
  --input-text: #{{ .input_text }};
  --font-family: {{ .font_family }};
  --font-size: {{ .font_size }};
  --heading-weight: {{ .heading_weight }};
  --card-radius: {{ .card_radius }};
  --card-border-width: {{ .card_border_width }};
  --card-shadow: {{ if eq .card_shadow "none" }}none{{ else if eq .card_shadow "strong" }}0 24px 60px rgba(15, 12, 40, 0.22){{ else }}0 12px 32px rgba(15, 12, 40, 0.10){{ end }};
  --control-radius: {{ .control_radius }};
  --button-weight: {{ .button_weight }};
  --logo-height: {{ .logo_height }};
  --logo-align: {{ if eq .logo_align "left" }}flex-start{{ else }}center{{ end }};
  --brand-text-align: {{ if eq .logo_align "left" }}left{{ else }}center{{ end }};
}
